// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public {
        c = new ERCDDAToken(1000, "Test", "TST");
    }
    function testFuzz_property(uint256 burnAmount, uint8 randomSeed) public {
        uint256 ownerBalance = c.balanceOf(address(this));
        vm.assume(burnAmount > 0);
        vm.assume(burnAmount <= ownerBalance);
        vm.assume(randomSeed < 10);

        uint256 totalSupplyBefore = c.totalSupply();
        bool ok;
        try c.burn(burnAmount) returns (bool result) {
            ok = result;
        } catch {
            ok = false;
        }
        require(ok, "Burn failed unexpectedly");

        uint256 totalSupplyAfter = c.totalSupply();
        assertTrue(totalSupplyAfter == totalSupplyBefore - burnAmount);
    }
}
